# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÖRNEK VAAZ METNİ ÇÖZÜMLEME VE PLANLAMA AŞAMALARI</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Giriş (Mukaddime)</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• Eûzü-Besmele, Hamdele</text>\n  <text x="50" y="120" font-size="10.5" fill="#475569">ve Salvele ile başlangıç.</text>\n  <text x="40" y="143" font-size="11" fill="#334155">• Cemaate samimi hitap</text>\n  <text x="50" y="160" font-size="10.5" fill="#475569">(&quot;Muhterem Müslümanlar!&quot;).</text>\n  <text x="40" y="183" font-size="11" fill="#334155">• Konunun önemini belirten</text>\n  <text x="50" y="200" font-size="10.5" fill="#475569">serlevha ayet veya hadis.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Gelişme (Tahlil ve İrşat)</text>\n  <text x="262" y="103" font-size="11" fill="#334155">• Ayet ve sahih hadislerin</text>\n  <text x="272" y="120" font-size="10.5" fill="#475569">bağlamına uygun açıklanması.</text>\n  <text x="262" y="143" font-size="11" fill="#334155">• Siyer ve İslam tarihinden</text>\n  <text x="272" y="160" font-size="10.5" fill="#475569">ibretlik tablolar sunulması.</text>\n  <text x="262" y="183" font-size="11" fill="#334155">• Güncel hayatla ve ahlaki</text>\n  <text x="272" y="200" font-size="10.5" fill="#475569">sorumluluklarla ilişkilendirme.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Sonuç ve Dua (Hâtime)</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Ana mesajın birkaç özlü</text>\n  <text x="495" y="120" font-size="10.5" fill="#475569">cümleyle toparlanması.</text>\n  <text x="485" y="143" font-size="11" fill="#334155">• Davranışa dönüştürülebilir</text>\n  <text x="495" y="160" font-size="10.5" fill="#475569">somut tavsiyeler verilmesi.</text>\n  <text x="485" y="183" font-size="11" fill="#334155">• Ezandan önce içten bir</text>\n  <text x="495" y="200" font-size="10.5" fill="#475569">dua ile vaazın tamamlanması.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KÜRSÜDE İLETİŞİM, SES TONU VE BEDEN DİLİ İLKELERİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ses Tonu, Vurgu ve Diksiyon</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Tekdüze (monoton) veya aşırı bağıran</text>\n  <text x="60" y="120" font-size="10.5" fill="#475569">ses tonundan kaçınılmalıdır.</text>\n  <text x="50" y="143" font-size="11" fill="#334155">• Ayet ve hadis metinleri tecvit ve</text>\n  <text x="60" y="160" font-size="10.5" fill="#475569">mahreç kurallarına uygun okunmalıdır.</text>\n  <text x="50" y="183" font-size="11" fill="#334155">• Anlamın gerektirdiği yerlerde ses</text>\n  <text x="60" y="200" font-size="10.5" fill="#475569">alçaltılıp yükseltilerek dikkat tutulur.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Göz Teması ve Beden Dili</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Metne bağımlı kalıp sürekli kâğıttan</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">okumak yerine irticalen (doğaçlama) sunum.</text>\n  <text x="380" y="143" font-size="11" fill="#334155">• Cemaatin tamamını kuşatan dengeli</text>\n  <text x="390" y="160" font-size="10.5" fill="#475569">göz teması ve mütebessim çehre.</text>\n  <text x="380" y="183" font-size="11" fill="#334155">• Vakara uygun jest ve mimikler;</text>\n  <text x="390" y="200" font-size="10.5" fill="#475569">tebliğde &quot;tebşîr&quot; (müjdeleme) üslubu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VAAZ SUNUMUNU DEĞERLENDİRME ÖLÇÜTLERİ (HMU.11.2.1)</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İçerik ve Kaynak Güveni</text>\n  <text x="40" y="105" font-size="10.5" fill="#334155">• Konu bütünlüğü korundu mu?</text>\n  <text x="40" y="127" font-size="10.5" fill="#334155">• Ayet mealleri ve sahih hadis</text>\n  <text x="48" y="144" font-size="10.5" fill="#475569">kaynakları doğru aktarıldı mı?</text>\n  <text x="40" y="167" font-size="10.5" fill="#334155">• Uydurma (mevzû) rivayetlerden</text>\n  <text x="48" y="184" font-size="10.5" fill="#475569">ve hurafelerden kaçınıldı mı?</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Üslup ve Hitabet Gücü</text>\n  <text x="262" y="105" font-size="10.5" fill="#334155">• Kuşatıcı, birleştirici ve</text>\n  <text x="270" y="122" font-size="10.5" fill="#475569">hikmetli bir dil kullanıldı mı?</text>\n  <text x="262" y="145" font-size="10.5" fill="#334155">• Cemaatin kültür ve yaş</text>\n  <text x="270" y="162" font-size="10.5" fill="#475569">seviyesine hitap edildi mi?</text>\n  <text x="262" y="185" font-size="10.5" fill="#334155">• Ses tonu ve göz teması</text>\n  <text x="270" y="202" font-size="10.5" fill="#475569">etkili biçimde yönetildi mi?</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Zaman ve Kürsü Âdâbı</text>\n  <text x="485" y="105" font-size="10.5" fill="#334155">• Vaaz süresi (25-30 dk)</text>\n  <text x="493" y="122" font-size="10.5" fill="#475569">verimli kullanıldı mı?</text>\n  <text x="485" y="145" font-size="10.5" fill="#334155">• Ezan okunmaya başlamadan</text>\n  <text x="493" y="162" font-size="10.5" fill="#475569">dua ile vaaz bitirildi mi?</text>\n  <text x="485" y="185" font-size="10.5" fill="#334155">• Öz ve akran değerlendirmesi</text>\n  <text x="493" y="202" font-size="10.5" fill="#475569">ile eksikler tespit edildi mi?</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
